package com.bank.query.repository;

import com.bank.query.model.Account;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // 1) DERIVED METHOD: name parsed into a query
    List<Account> findByStatusAndBalanceGreaterThan(String status, BigDecimal min);

    // 2) JPQL via @Query: explicit, clean method name, full control
    @Query("select a from Account a where a.balance > :min and a.status = :status " +
           "order by a.balance desc")
    List<Account> highValue(@Param("min") BigDecimal min, @Param("status") String status);

    // 3) NATIVE SQL: PostgreSQL window function JPQL cannot express
    @Query(value = "select *, rank() over (order by balance desc) as rnk " +
                   "from accounts where status = :status", nativeQuery = true)
    List<Account> rankedByBalance(@Param("status") String status);

    // 4) @Modifying bulk UPDATE: freeze dormant accounts in one statement
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("update Account a set a.status = 'FROZEN' where a.lastActivity < :cutoff")
    int freezeDormant(@Param("cutoff") LocalDate cutoff);
}
```

