// ─── File: src/main/java/com/bank/query/service/AccountQueryService.java ───
package com.bank.query.service;

import com.bank.query.model.Account;
import com.bank.query.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class AccountQueryService {
    private final AccountRepository repo;

    @Transactional(readOnly = true)
    public List<Account> search(String status, BigDecimal min) {
        return repo.findByStatusAndBalanceGreaterThan(status, min);  // derived
    }

    @Transactional(readOnly = true)
    public List<Account> highValue(BigDecimal min) {
        return repo.highValue(min, "ACTIVE");                        // JPQL
    }

    @Transactional(readOnly = true)
    public List<Account> ranked() {
        return repo.rankedByBalance("ACTIVE");                       // native
    }

    // @Modifying must run in a (writable) transaction
    @Transactional
    public int freezeDormantBefore(LocalDate cutoff) {
        int frozen = repo.freezeDormant(cutoff);                     // bulk UPDATE
        log.warning(() -> "Froze " + frozen + " dormant accounts");
        return frozen;
    }
}
```
